    /**
     * Method to retrieve the PaymentProcessor via PaymentProcessorFetchOneSummary
     * @param 	summary PaymentProcessorFetchOneSummary 
     * @return 	PaymentProcessorFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public PaymentProcessor getPaymentProcessor( PaymentProcessorFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "PaymentProcessorFetchOneSummary arg cannot be null" );
    	
    	PaymentProcessor entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a PaymentProcessor
        	// --------------------------------------
        	CompletableFuture<PaymentProcessor> futureEntity = queryGateway.query(new FindPaymentProcessorQuery( new LoadPaymentProcessorFilter( summary.getPaymentProcessorId() ) ), ResponseTypes.instanceOf(PaymentProcessor.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate PaymentProcessor with id " + summary.getPaymentProcessorId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


